[$['data']['slides'][0]['description']['original']] <div class="container">
    <div class="loan-calculator" id="loan-calculator__mrt">
        <div class="loan-calculator__info">
            <p class="features3-grid__adt paragraph-small">Mortgage calculator</p>
            <h2 class="features3-grid__block-title">Mortgage calculator</h2>
            <p class="loan-calculator__info-text">Restriction applies to entry of values as per the Bank’s terms.</p>
            <div class="loan-calculator__item">
                <p class="paragraph-small">Annual interest rate (%)</p>
                <input class="loan-calculator__rate-number" type="number" min="12.5" max="14" value="12.5" step=".5" />
                <input class="loan-calculator__rate-range" type="range" min="12.5" max="14" value="12.5" step=".5" />
                <p class="loan-calculator__item-text paragraph-small"><span>12.5 %</span><span>14 %</span></p>
            </div>
            <div class="loan-calculator__item">
                <p class="paragraph-small">Mortgage loan amount (AMD)</p>
                <input class="loan-calculator__amount-number" type="number" min="3000000" max="150000000" value="20000000" step="10000" />
                <input class="loan-calculator__amount-range" type="range" min="3000000" max="150000000" value="20000000" step="10000" />
                <p class="loan-calculator__item-text paragraph-small"><span>3,000,000</span><span>150,000,000</span></p>
            </div>
            <div class="loan-calculator__item">
                <p class="paragraph-small">Mortgage loan term (months)</p>
                <input class="loan-calculator__mounths-number" type="number" min="60" max="360" value="240" />
                <input class="loan-calculator__mounths-range" type="range" min="60" max="360" value="240" />
                <p class="loan-calculator__item-text paragraph-small"><span>60</span><span>360</span></p>
            </div>
        </div>
        <div class="loan-calculator__result">
            <div class="loan-calculator__result-row">
                <p class="loan-calculator__result-title paragraph-small font-bold">MONTHLY INSTALLMENT

</p>
                <div class="loan-calculator__mounthly-wrapper">
                    <p class="loan-calculator__mounthly-payment font-bold"></p>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none">
