                        <div>
                            <p class="loan-calculator__interest-amount paragraph-small font-bold"></p>
                            <p class="paragraph-small font-bold">
AMD</p>
                        </div>
                    </div>
                </div>
                <p class="paragraph-xsmall">Dear Client, this calculation is for information only and might be changed

</p>
                <div class="loan-calculator__result-footer">
                     <a class="button button_primary estate" href="https://myhome.am" target="blank">Apply online</a>
                </div>
            </div>
        </div>
    </div>
