<script>
    /* loan calculator */
    $(document).ready(function() {
        setTimeout(function () {

            function mortgageCalculator() {
                const mainElement = $("#loan-calculator__mrt"); 

                if(mainElement.length) {

                    function calculateLoanPayment(loanAmount, interestRate, maturityMounths) {
                        const monthlyRate = (interestRate / 100) / 12;
                        const payment = (loanAmount * monthlyRate) / (1 - Math.pow((1 + monthlyRate), -maturityMounths));
                
                        const mounthlyPayment = parseInt(payment);
                        const totalAmount = parseInt(payment * maturityMounths);
                        const interestAmount = parseInt(totalAmount - loanAmount);
                
                        const moneyFormatter  = new Intl.NumberFormat();
                
                        $("#loan-calculator__mrt .loan-calculator__mounthly-payment").text(moneyFormatter.format(mounthlyPayment));
                        $("#loan-calculator__mrt .loan-calculator__total-amount").text(moneyFormatter.format(totalAmount));
                        $("#loan-calculator__mrt .loan-calculator__interest-amount").text(moneyFormatter.format(interestAmount));
                    }
                
                    const rangeRate = document.querySelector('#loan-calculator__mrt .loan-calculator__rate-range');
                    const numberRate = document.querySelector('#loan-calculator__mrt .loan-calculator__rate-number');
                    const rangeAmount = document.querySelector('#loan-calculator__mrt .loan-calculator__amount-range');
                    const numberAmount = document.querySelector('#loan-calculator__mrt .loan-calculator__amount-number');
                    const rangeMounths = document.querySelector('#loan-calculator__mrt .loan-calculator__mounths-range');
                    const numberMounths = document.querySelector('#loan-calculator__mrt .loan-calculator__mounths-number');
                
                    validateMinMax(rangeRate, numberRate, 12.5, 14);
                    validateMinMaxAmount(rangeAmount, numberAmount, 3000000, 150000000);
                    validateMinMax(rangeMounths, numberMounths, 60, 360);

                    calculateLoanPayment(numberAmount.value.split(',').join(""), numberRate.value, numberMounths.value);

                    function validateMinMaxAmount(rangeField, numberField, minValue, maxValue) {
                        numberField.type=''; 
                        numberField.value=numberField.value==''?'':(+numberField.value).toLocaleString();

                        rangeField.addEventListener('input', function (e) {
                            if (e.target.value < minValue) {
                                rangeField.value = minValue;
                                numberField.value = minValue;
                            } else if (e.target.value > maxValue) {
                                rangeField.value = maxValue;
                                numberField.value = maxValue;
                            } else {
                                numberField.type=''; 
                                numberField.value=numberField.value==''?'':(+e.target.value).toLocaleString();
                            }

                            let numberAmountConverted = numberAmount.value.split(',').join("");
                            calculateLoanPayment(numberAmountConverted, numberRate.value, numberMounths.value);
                        });

                        numberField.addEventListener("focus", function(e) {
                            this.value = this.value.split(',').join("");
                            this.type='number'; 
                        });

                        numberField.addEventListener('focusout', function (e) {
                            if (e.target.value < minValue) {
                                rangeField.value = minValue;
                                this.type=''; 
                                numberField.value = (+minValue).toLocaleString();
                            } else if (e.target.value > maxValue) {
                                rangeField.value = maxValue;
                                this.type=''; 
                                numberField.value = (+maxValue).toLocaleString();
                            } else {
                                this.type=''; 
                                this.value=this.value==''?'':(+this.value).toLocaleString();
                                rangeField.value = this.value.split(',').join("");
                            }

                            let numberAmountConverted = numberAmount.value.split(',').join("");
                            calculateLoanPayment(numberAmountConverted, numberRate.value, numberMounths.value);
                        });
                    }
                
                    function validateMinMax(rangeField, numberField, minValue, maxValue) {
                        rangeField.addEventListener('input', function (e) {
                            if (e.target.value < minValue) {
                                numberField.value = minValue;
                                rangeField.value = minValue;
                            } else if (e.target.value > maxValue) {
                                rangeField.value = maxValue;
                                numberField.value = maxValue;
                            } else {
                                numberField.value = e.target.value;
                            }

                            let numberAmountConverted = numberAmount.value.split(',').join("");
                            calculateLoanPayment(numberAmountConverted, numberRate.value, numberMounths.value);
                        });
                        numberField.addEventListener('focusout', function (e) {
                            if (e.target.value < minValue) {
                                numberField.value = minValue;
                                rangeField.value = minValue;
                            } else if (e.target.value > maxValue) {
                                rangeField.value = maxValue;
                                numberField.value = maxValue;
                            } else {
                                rangeField.value = e.target.value;
                            }

                            let numberAmountConverted = numberAmount.value.split(',').join("");
                            calculateLoanPayment(numberAmountConverted, numberRate.value, numberMounths.value);
                        });
                    }
                    
                }
            }
        
            mortgageCalculator();

        }, 1000);
    });
</script>
